// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { element, fragment } from 'tsx-vanilla';

import { DamageDealtLog, Entity, SimLog } from '../../proto_utils/logs_parser.js';

// Structured log filters, backported from wowsims/mop's LogRunner (model/log/search). Each group is
// one field with one or more values; a line must pass every group, and within a group the values are
// joined by AND or OR. The free-text search still applies on top of the groups.

export const FILTER_FIELDS = ['source', 'target', 'spell', 'type', 'outcome', 'time', 'amount'] as const;
export type FilterField = (typeof FILTER_FIELDS)[number];

export type FilterGroup = { field: FilterField; join: 'and' | 'or'; values: Array<string> };

/** Fields whose values are typed into a box rather than picked, and the placeholder each shows. */
const TYPED_FIELDS: Partial<Record<FilterField, string>> = { time: '10-30', amount: '>5000' };

export const DEBUG_MARKER = '[DEBUG]';

const isDebug = (log: SimLog) => log.raw.includes(DEBUG_MARKER);

// damage/heal/shield select the effect, so they partition damage-dealt lines instead of overlapping;
// a miss has no effect and matches none of them. periodic/direct split the same lines by tick.
const TYPE_FILTERS: Record<string, (log: SimLog) => boolean> = {
	damage: log => log.isDamageDealt() && log.isDamage(),
	heal: log => log.isDamageDealt() && log.isHealing(),
	shield: log => log.isDamageDealt() && log.isShielding(),
	periodic: log => log.isDamageDealt() && log.tick,
	direct: log => log.isDamageDealt() && !log.tick,
	resource: log => log.isResourceChanged(),
	aura: log => log.isAuraEvent() || log.isAuraStacksChange(),
	cast: log => log.isCastBegan(),
	'major-cooldown': log => log.isMajorCooldownUsed(),
	'stat-change': log => log.isStatChange(),
	debug: isDebug,
};

const OUTCOMES = ['hit', 'crit', 'miss', 'dodge', 'parry', 'glance', 'block', 'crush'] as const;

// One outcome per line, in the same precedence the log line itself prints it (a critical block is a block).
export function outcomeOf(log: DamageDealtLog): (typeof OUTCOMES)[number] {
	if (log.miss) return 'miss';
	if (log.dodge) return 'dodge';
	if (log.parry) return 'parry';
	if (log.glance) return 'glance';
	if (log.block) return 'block';
	if (log.crit) return 'crit';
	if (log.crush) return 'crush';
	return 'hit';
}

type NumericFilter = { min: number; minInclusive: boolean; max: number; maxInclusive: boolean };

// Accepts 'a-b' ranges and '>', '>=', '<', '<=', '=' comparisons; a bare number is exact.
// The range separator and a negative sign are both '-', but the number pattern only stops
// consuming at a non-digit, so '-5-10' still splits into -5 and 10.
function parseNumericFilter(value: string): NumericFilter | null {
	const trimmed = value.trim();
	const range = /^(-?\d+(?:\.\d+)?)\s*-\s*(-?\d+(?:\.\d+)?)$/.exec(trimmed);
	if (range) {
		const a = Number(range[1]);
		const b = Number(range[2]);
		return { min: Math.min(a, b), minInclusive: true, max: Math.max(a, b), maxInclusive: true };
	}
	const cmp = /^(>=|<=|>|<|=)?(-?\d+(?:\.\d+)?)$/.exec(trimmed);
	if (cmp) {
		const n = Number(cmp[2]);
		switch (cmp[1]) {
			case '>':
				return { min: n, minInclusive: false, max: Infinity, maxInclusive: true };
			case '>=':
				return { min: n, minInclusive: true, max: Infinity, maxInclusive: true };
			case '<':
				return { min: -Infinity, minInclusive: true, max: n, maxInclusive: false };
			case '<=':
				return { min: -Infinity, minInclusive: true, max: n, maxInclusive: true };
			default:
				return { min: n, minInclusive: true, max: n, maxInclusive: true };
		}
	}
	return null;
}

const inRange = (f: NumericFilter, n: number) =>
	(f.minInclusive ? n >= f.min : n > f.min) && (f.maxInclusive ? n <= f.max : n < f.max);

const entityLabel = (entity: Entity | null) => entity?.toString() ?? '';

function matcherFor(field: FilterField, value: string): (log: SimLog) => boolean {
	switch (field) {
		case 'source':
			return log => entityLabel(log.source) === value;
		case 'target':
			return log => entityLabel(log.target) === value;
		case 'spell':
			return log => log.actionId?.name === value;
		case 'type':
			return TYPE_FILTERS[value] ?? (() => false);
		case 'outcome':
			return log => log.isDamageDealt() && outcomeOf(log) === value;
		case 'time': {
			const f = parseNumericFilter(value);
			return f ? log => inRange(f, log.timestamp) : () => false;
		}
		// Damage-dealt lines only: a miss still has an amount (0) and is included, nothing else is.
		case 'amount': {
			const f = parseNumericFilter(value);
			return f ? log => log.isDamageDealt() && inRange(f, log.amount) : () => false;
		}
	}
}

/**
 * Compiles the groups into one predicate. A group with no values is a field picked but not yet
 * filled: it is ignored, rather than matching nothing.
 */
export function compileFilter(groups: ReadonlyArray<FilterGroup>): (log: SimLog) => boolean {
	const compiled = groups
		.filter(group => group.values.length)
		.map(group => {
			const matchers = group.values.map(value => matcherFor(group.field, value));
			return group.join === 'and'
				? (log: SimLog) => matchers.every(m => m(log))
				: (log: SimLog) => matchers.some(m => m(log));
		});
	return log => compiled.every(group => group(log));
}

/** An explicit type:debug filter asks for the lines the debug toggle hides, so it wins over the toggle. */
export const groupsWantDebug = (groups: ReadonlyArray<FilterGroup>) =>
	groups.some(group => group.field === 'type' && group.values.includes('debug'));

export type FilterSuggestions = { units: Array<string>; spells: Array<string> };

export function buildSuggestions(logs: ReadonlyArray<SimLog>): FilterSuggestions {
	const units = new Set<string>();
	const spells = new Set<string>();
	for (const log of logs) {
		if (log.source) units.add(entityLabel(log.source));
		if (log.target) units.add(entityLabel(log.target));
		if (log.actionId?.name) spells.add(log.actionId.name);
	}
	return { units: [...units].sort(), spells: [...spells].sort((a, b) => a.localeCompare(b)) };
}

const sentenceCase = (text: string) => (text ? text.charAt(0).toUpperCase() + text.slice(1) : text);
const labelOf = (field: FilterField, value: string) => (field === 'type' || field === 'outcome' ? sentenceCase(value.replace(/-/g, ' ')) : value);

function valueCandidates(field: FilterField, suggestions: FilterSuggestions): ReadonlyArray<string> {
	switch (field) {
		case 'type':
			return Object.keys(TYPE_FILTERS);
		case 'outcome':
			return OUTCOMES;
		case 'spell':
			return suggestions.spells;
		case 'source':
		case 'target':
			return suggestions.units;
		default:
			return [];
	}
}

/** The "No filters" toggle plus the panel of filter groups it opens. */
export class LogFilterPanel {
	readonly toggleButton: HTMLButtonElement;
	readonly panel: HTMLDivElement;

	private groups: Array<FilterGroup> = [];
	private suggestions: FilterSuggestions = { units: [], spells: [] };
	private open = false;

	constructor(private readonly onChange: (groups: ReadonlyArray<FilterGroup>) => void) {
		this.toggleButton = (<button className="btn btn-primary log-filter-toggle" aria-expanded="false"></button>) as HTMLButtonElement;
		this.toggleButton.addEventListener('click', () => this.setOpen(!this.open));
		this.panel = (<div className="log-filter-panel d-none"></div>) as HTMLDivElement;
		this.render();
	}

	getGroups(): ReadonlyArray<FilterGroup> {
		return this.groups;
	}

	setSuggestions(suggestions: FilterSuggestions) {
		this.suggestions = suggestions;
		this.render();
	}

	private setOpen(open: boolean) {
		this.open = open;
		this.panel.classList.toggle('d-none', !open);
		this.toggleButton.setAttribute('aria-expanded', String(open));
	}

	private update(groups: Array<FilterGroup>) {
		this.groups = groups;
		this.render();
		this.onChange(this.groups);
	}

	private updateGroup(index: number, group: FilterGroup | null) {
		const next = [...this.groups];
		if (group) next[index] = group;
		else next.splice(index, 1);
		this.update(next);
	}

	private render() {
		const active = this.groups.filter(group => group.values.length).length;
		this.toggleButton.replaceChildren(
			<>
				<i className="fas fa-filter me-1"></i>
				{active ? `${active} filter${active > 1 ? 's' : ''}` : 'No filters'}
			</>,
		);
		this.toggleButton.classList.toggle('active', active > 0);

		const fieldPicker = (
			<select className="form-select form-select-sm log-filter-add">
				<option value="" selected>
					Add filter…
				</option>
				{FILTER_FIELDS.map(field => (
					<option value={field}>{sentenceCase(field)}</option>
				))}
			</select>
		) as HTMLSelectElement;
		fieldPicker.addEventListener('change', () => {
			const field = fieldPicker.value as FilterField;
			if (field) this.update([...this.groups, { field, join: 'or', values: [] }]);
		});

		const clearButton = (
			<button className="btn btn-sm btn-outline-danger log-filter-clear">
				<i className="fas fa-times me-1"></i>Clear filters
			</button>
		) as HTMLButtonElement;
		clearButton.addEventListener('click', () => this.update([]));
		clearButton.classList.toggle('d-none', !this.groups.length);

		this.panel.replaceChildren(
			<>
				<div className="log-filter-panel-header">
					{fieldPicker}
					{clearButton}
					<span className="log-filter-hint">
						Every group must match. Inside a group, values combine with AND / OR. Time is in seconds.
					</span>
				</div>
				<div className="log-filter-groups">{this.groups.map((group, index) => this.renderGroup(group, index))}</div>
			</>,
		);
	}

	private renderGroup(group: FilterGroup, index: number): Element {
		const joinButtons = (['and', 'or'] as const).map(join => {
			const button = (
				<button className={`btn btn-sm ${group.join === join ? 'btn-primary' : 'btn-outline-primary'}`} aria-pressed={String(group.join === join)}>
					{join.toUpperCase()}
				</button>
			) as HTMLButtonElement;
			button.addEventListener('click', () => {
				if (group.join !== join) this.updateGroup(index, { ...group, join });
			});
			return button;
		});

		const removeButton = (
			<button className="btn btn-link link-danger p-0 log-filter-group-remove" aria-label={`Remove ${group.field} filter`}>
				<i className="fas fa-times fa-lg"></i>
			</button>
		) as HTMLButtonElement;
		removeButton.addEventListener('click', () => this.updateGroup(index, null));

		const chips = group.values.map((value, valueIndex) => {
			const chip = (
				<span className="log-filter-chip">
					{labelOf(group.field, value)}
					<button className="btn btn-link p-0 ms-1" aria-label={`Remove ${value}`}>
						<i className="fas fa-times"></i>
					</button>
				</span>
			) as HTMLSpanElement;
			chip.querySelector('button')!.addEventListener('click', () =>
				this.updateGroup(index, { ...group, values: group.values.filter((_, i) => i !== valueIndex) }),
			);
			return chip;
		});

		const addValue = (value: string) => {
			if (value && !group.values.includes(value)) this.updateGroup(index, { ...group, values: [...group.values, value] });
		};

		let adder: Element;
		const placeholder = TYPED_FIELDS[group.field];
		if (placeholder) {
			const input = (<input type="text" className="form-control form-control-sm" placeholder={placeholder} autocomplete="off" />) as HTMLInputElement;
			const commitButton = (
				<button className="btn btn-sm btn-primary" aria-label="Add value">
					<i className="fas fa-check"></i>
				</button>
			) as HTMLButtonElement;
			const commit = () => {
				const value = input.value.trim();
				const valid = parseNumericFilter(value) !== null;
				input.classList.toggle('is-invalid', !!value && !valid);
				if (valid) addValue(value);
			};
			input.addEventListener('keydown', event => {
				if (event.key !== 'Enter') return;
				event.preventDefault();
				commit();
			});
			commitButton.addEventListener('click', commit);
			adder = (
				<div className="input-group input-group-sm">
					{input}
					{commitButton}
				</div>
			);
		} else {
			const picker = (
				<select className="form-select form-select-sm">
					<option value="" selected>
						Add value…
					</option>
					{valueCandidates(group.field, this.suggestions)
						.filter(value => !group.values.includes(value))
						.map(value => (
							<option value={value}>{labelOf(group.field, value)}</option>
						))}
				</select>
			) as HTMLSelectElement;
			picker.addEventListener('change', () => addValue(picker.value));
			adder = picker;
		}

		return (
			<div className="log-filter-group">
				<div className="log-filter-group-head">
					<span className="log-filter-group-field">{sentenceCase(group.field)}</span>
					<div className="btn-group ms-auto">{joinButtons}</div>
					{removeButton}
				</div>
				<div className="log-filter-group-items">
					{chips}
					{adder}
				</div>
			</div>
		);
	}
}
